// Validate PDF text and prepare context for the AI call
const pdfText   = $json.text || '';
const formData  = $('1. Form - Patient Uploads Prescription').first().json;

const patientName   = (formData['Your Full Name']               || '').trim();
const patientEmail  = (formData['Your Email Address']           || '').trim();
const language      = (formData['Preferred Language for Explanation'] || 'English').trim();
const doctorName    = (formData['Doctor Name (optional)']       || '').trim();
const healthNotes   = (formData['Any health conditions or allergies to note'] || '').trim();
const processedAt   = new Date().toISOString();
const dateOnly      = processedAt.split('T')[0];

if (!patientName) throw new Error('Patient name is missing from the form.');
if (!patientEmail || !patientEmail.includes('@')) throw new Error('Valid patient email is required.');
if (!pdfText || pdfText.trim().length < 30) {
  throw new Error(
    'Could not read text from the PDF. This usually means the PDF is a scanned image.' +
    ' Please upload a digital PDF where the text can be selected and copied.'
  );
}

// Truncate long PDFs to keep within the AI context limits
const cleanText = pdfText
  .replace(/\n{3,}/g, '\n\n')
  .replace(/[ \t]{3,}/g, '  ')
  .trim()
  .substring(0, 5000);

return [{
  json: {
    patientName,
    patientEmail,
    language,
    doctorName,
    healthNotes,
    cleanText,
    processedAt,
    dateOnly
  }
}];

// Parse the AI response and merge with patient data
const resp      = $input.first().json;
const formCtx   = $('3. Code - Validate + Prepare Context').first().json;

const raw = resp?.choices?.[0]?.message?.content || '';

if (!raw) throw new Error('The AI returned an empty response. Check your OpenAI API credential and account credits.');

let rx = {};
try {
  const cleaned = raw.trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();
  const s = cleaned.indexOf('{');
  const e = cleaned.lastIndexOf('}');
  if (s !== -1 && e !== -1) rx = JSON.parse(cleaned.substring(s, e + 1));
  else throw new Error('No JSON object found in response');
} catch (err) {
  throw new Error('Failed to parse the AI response: ' + err.message + ' | Raw: ' + raw.substring(0, 200));
}

const medicines       = Array.isArray(rx.medicines) ? rx.medicines : [];
const medicinesCount  = medicines.length || parseInt(rx.medicinesCount) || 0;

if (medicinesCount === 0) {
  throw new Error('No medicines found in the prescription PDF. The PDF may be a scanned image or contain unreadable text.');
}

return [{
  json: {
    patientName:      formCtx.patientName,
    patientEmail:     formCtx.patientEmail,
    language:         formCtx.language,
    dateOnly:         formCtx.dateOnly,
    processedAt:      formCtx.processedAt,
    doctorName:       rx.doctorName       || formCtx.doctorName || 'Your Doctor',
    prescriptionDate: rx.prescriptionDate || formCtx.dateOnly,
    medicinesCount,
    medicines,
    generalAdvice:    rx.generalAdvice    || '',
    followUpNote:     rx.followUpNote     || 'Please follow your doctor instructions carefully.',
    status:           'Success'
  }
}];
